using Microsoft.EntityFrameworkCore;using Pedidos.Api.Models;
namespace Pedidos.Api.Data;
public sealed class PedidosDbContext(DbContextOptions<PedidosDbContext> options):DbContext(options){public DbSet<Cliente> Clientes=>Set<Cliente>();public DbSet<Pedido> Pedidos=>Set<Pedido>();public DbSet<DetallePedido> Detalles=>Set<DetallePedido>();protected override void OnModelCreating(ModelBuilder b){b.Entity<Cliente>().ToTable("Cliente").HasKey(x=>x.IdCliente);b.Entity<Pedido>(e=>{e.ToTable("Pedido");e.HasKey(x=>x.IdPedido);e.HasOne(x=>x.Cliente).WithMany(x=>x.Pedidos).HasForeignKey(x=>x.IdCliente);});b.Entity<DetallePedido>(e=>{e.ToTable("DetallePedido");e.HasKey(x=>x.IdDetallePedido);e.Property(x=>x.PrecioUnitario).HasPrecision(10,2);e.HasOne(x=>x.Pedido).WithMany(x=>x.Detalles).HasForeignKey(x=>x.IdPedido);});}}
